def _tokenize(s):
    """Tokenize Scheme source into a list of tokens.
    Each token is one of:
    - '(' or ')' (string)
    - '#' (string, for #t, #f)
    - "'" (string, for quote)
    - an integer (Python int)
    - a string (Python str, for string literals)
    - a symbol (Python str, for the name)
    - '#' (for booleans, we'll handle #t and #f)
    """
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in ' \t\n\r':
            i += 1
        elif c == ';':
            # Comment to end of line
            while i < n and s[i] != '\n':
                i += 1
        elif c == '(':
            tokens.append(('lparen', '('))
            i += 1
        elif c == ')':
            tokens.append(('rparen', ')'))
            i += 1
        elif c == "'":
            tokens.append(('quote', "'"))
            i += 1
        elif c == '#':
            if i + 1 < n and s[i+1] == 't':
                tokens.append(('bool', True))
                i += 2
            elif i + 1 < n and s[i+1] == 'f':
                tokens.append(('bool', False))
                i += 2
            else:
                raise SchemeError("syntax error: invalid # token")
        elif c == '"':
            # String literal
            i += 1
            buf = []
            while i < n:
                c = s[i]
                if c == '\\':
                    if i + 1 < n:
                        nc = s[i+1]
                        if nc == '"':
                            buf.append('"')
                            i += 2
                        elif nc == '\\':
                            buf.append('\\')
                            i += 2
                        elif nc == 'n':
                            buf.append('\n')
                            i += 2
                        else:
                            raise SchemeError("syntax error: invalid escape")
                    else:
                        raise SchemeError("syntax error: unterminated string")
                elif c == '"':
                    i += 1
                    tokens.append(('string', ''.join(buf)))
                    break
                else:
                    buf.append(c)
                    i += 1
            else:
                raise SchemeError("syntax error: unterminated string")
        else:
            # Read a token (symbol or number)
            start = i
            while i < n and s[i] not in ' \t\n\r()";\'':
                i += 1
            token = s[start:i]
            # Check if it's an integer
            if re.fullmatch(r'[+-]?[0-9]+', token):
                tokens.append(('int', int(token)))
            else:
                tokens.append(('sym', token))
    return tokens
```

